actions.script:
def access = ec.service.sync().name('zenith.base.SecurityServices.check#ModuleWriteAccess').parameter('moduleId',kitchenModuleId ?: 'pos').call()
def org = posOrganizationPartyId
if (access?.canWrite != true || !(ec.user.isInGroup('ADMIN') || ec.user.isInGroup('ZENITH_ADMIN')) || !org) { ec.message.addError('Select a shop with POS administrator access first.'); return }
def name = (modeName ?: '').toString().trim()
def code = (modeCode ?: '').toString().trim().toUpperCase(java.util.Locale.ROOT)
if (!name || name.length() > 100 || !(code ==~ /[A-Z0-9_]{2,12}/)) { ec.message.addError('Enter a mode name and a 2-12 character code using letters, numbers or underscore.'); return }
if (!['PpsMrp','PpsDiscountMrp','PpsFixedProduct'].contains(priceSource)) { ec.message.addError('Choose a supported price source.'); return }
def disc, markup, minimum
try { disc = (discountPercent ?: '0') as BigDecimal; markup = (markupPercent ?: '0') as BigDecimal; minimum = (minOrderAmount ?: '0') as BigDecimal }
catch (Exception ignored) { ec.message.addError('Enter valid numeric pricing values.'); return }
if (disc < 0 || disc > 100 || markup < 0 || minimum < 0) { ec.message.addError('Discount must be 0-100%; markup and minimum must be non-negative.'); return }
def availableModes = ec.service.sync().name('zenith.pos.PosModeServices.get#OrganizationModes')
    .parameter('organizationPartyId',org).call().modes
def reservedModeIds = (availableModes*.salesModeId + ['RETAIL','WHOLESALE']) as Set
if (ec.entity.find('zenith.erp.pos.PosSalesMode').condition('modeCode',code).list().any {
    it.organizationPartyId == org || reservedModeIds.contains(it.salesModeId)
}) { ec.message.addError('A sales mode with this code already exists for this shop.'); return }
def newMode = ec.entity.makeValue('zenith.erp.pos.PosSalesMode').setAll([
    organizationPartyId:org, modeName:name, modeCode:code, priceSource:priceSource,
    discountPercent:disc, markupPercent:markup, minOrderAmount:minimum,
    isTaxInclusive:(isTaxInclusive == 'Y' ? 'Y' : 'N'), requireCustomer:(requireCustomer == 'Y' ? 'Y' : 'N'),
    invoicePrefix:(invoicePrefix ?: '').toString().trim().take(20),
    colorCode:((colorCode ?: '') ==~ /#[0-9a-fA-F]{6}/ ? colorCode : '#7C3AED'),
    isDefault:'N', isActive:'Y', description:(description ?: '').toString().trim().take(1000)
]).setSequencedIdPrimary()
newMode.create()
// Existing terminal assignments are restrictive. Make a newly created mode
// available immediately at this shop; admins can remove individual assignments.
def availableModeIds = availableModes*.salesModeId
ec.entity.find('zenith.erp.pos.PosTerminal').condition('organizationPartyId',org).condition('isActive','Y').list().each { terminal ->
    def assigned = availableModeIds && ec.entity.find('zenith.erp.pos.PosTerminalSalesMode')
        .condition('terminalId',terminal.terminalId).condition('isActive','Y').condition('salesModeId','in',availableModeIds).count() > 0
    // Preserve the existing choices when a terminal gets its first visible mapping.
    def modesToAssign = assigned ? [newMode] : availableModes + [newMode]
    modesToAssign.each { mode ->
        ec.service.sync().name('store#zenith.erp.pos.PosTerminalSalesMode').parameters([
            terminalId:terminal.terminalId, salesModeId:mode.salesModeId, isActive:'Y'
        ]).call()
    }
}

def access = ec.service.sync().name('zenith.base.SecurityServices.check#ModuleWriteAccess').parameter('moduleId',kitchenModuleId ?: 'pos').call()
def org = posOrganizationPartyId
def mode = salesModeId ? ec.entity.find('zenith.erp.pos.PosSalesMode').condition('salesModeId',salesModeId).forUpdate(true).one() : null
if (access?.canWrite != true || !(ec.user.isInGroup('ADMIN') || ec.user.isInGroup('ZENITH_ADMIN')) || !org || mode?.organizationPartyId != org || mode.isActive != 'Y') { ec.message.addError('This shop cannot edit that sales mode.'); return }
if (ec.entity.find('zenith.erp.pos.PosTransaction').condition('organizationPartyId',org).condition('salesModeId',salesModeId).condition('statusId','PtCreated').count() > 0) { ec.message.addError('Finish or void open carts in this mode before changing it.'); return }
def disc, markup, minimum
try {
    disc = (discountPercent ?: '0') as BigDecimal
    markup = (ec.web.parameters.containsKey('markupPercent') ? (markupPercent ?: '0') : (mode.markupPercent ?: 0)) as BigDecimal
    minimum = (ec.web.parameters.containsKey('minOrderAmount') ? (minOrderAmount ?: '0') : (mode.minOrderAmount ?: 0)) as BigDecimal
} catch (Exception ignored) { ec.message.addError('Enter valid numeric pricing values.'); return }
if (disc < 0 || disc > 100 || markup < 0 || minimum < 0) { ec.message.addError('Discount must be 0-100%; markup and minimum must be non-negative.'); return }
def code = (modeCode ?: '').toString().trim().toUpperCase(java.util.Locale.ROOT)
if (!(code ==~ /[A-Z0-9_]{2,12}/)) { ec.message.addError('Use a 2-12 character code.'); return }
def availableModes = ec.service.sync().name('zenith.pos.PosModeServices.get#OrganizationModes')
    .parameter('organizationPartyId',org).call().modes
def reservedModeIds = (availableModes*.salesModeId + ['RETAIL','WHOLESALE']) as Set
if (ec.entity.find('zenith.erp.pos.PosSalesMode').condition('modeCode',code).list().any {
    it.salesModeId != salesModeId && (it.organizationPartyId == org || reservedModeIds.contains(it.salesModeId))
}) { ec.message.addError('That mode code already exists.'); return }
def prefix = ec.web.parameters.containsKey('invoicePrefix') ? (invoicePrefix ?: '').toString().trim() : (mode.invoicePrefix ?: '')
def color = ec.web.parameters.containsKey('colorCode') ? (colorCode ?: '').toString().trim() : (mode.colorCode ?: '#7C3AED')
if (prefix.length() > 20 || !(color ==~ /#[0-9a-fA-F]{6}/)) { ec.message.addError('Use an invoice prefix up to 20 characters and a valid six-digit color code.'); return }
mode.setAll([modeName:(modeName ?: '').toString().trim().take(100), modeCode:code,
    priceSource:(['PpsMrp','PpsDiscountMrp','PpsFixedProduct'].contains(priceSource) ? priceSource : mode.priceSource),
    discountPercent:disc, markupPercent:markup, minOrderAmount:minimum,
    invoicePrefix:prefix, colorCode:color,
    description:(ec.web.parameters.containsKey('description') ? (description ?: '').toString().trim().take(1000) : mode.description),
    isTaxInclusive:(isTaxInclusive == 'Y' ? 'Y' : 'N'),
    requireCustomer:(requireCustomer == 'Y' ? 'Y' : 'N'),
    isActive:(ec.web.parameters.containsKey('isActive') ? (isActive == 'N' ? 'N' : 'Y') : mode.isActive)])
if (!mode.modeName) { ec.message.addError('Mode name is required.'); return }
mode.update()

def org = posOrganizationPartyId
def access = ec.service.sync().name('zenith.base.SecurityServices.check#ModuleWriteAccess').parameter('moduleId',kitchenModuleId ?: 'pos').call()
def terminal = terminalId ? ec.entity.find('zenith.erp.pos.PosTerminal').condition('terminalId',terminalId).one() : null
if (access?.canWrite != true || !(ec.user.isInGroup('ADMIN') || ec.user.isInGroup('ZENITH_ADMIN')) || !org || terminal?.organizationPartyId != org) { ec.message.addError('Choose a terminal and active mode from this shop.'); return }
def availableModes = ec.service.sync().name('zenith.pos.PosModeServices.get#OrganizationModes')
    .parameter('organizationPartyId',org).call().modes
if (!availableModes.any { it.salesModeId == salesModeId }) { ec.message.addError('Choose an active sales mode from this organization.'); return }
ec.service.sync().name('store#zenith.erp.pos.PosTerminalSalesMode').parameters([terminalId:terminalId,salesModeId:salesModeId,isActive:'Y']).call()

def org = posOrganizationPartyId
def access = ec.service.sync().name('zenith.base.SecurityServices.check#ModuleWriteAccess').parameter('moduleId',kitchenModuleId ?: 'pos').call()
def terminal = terminalId ? ec.entity.find('zenith.erp.pos.PosTerminal').condition('terminalId',terminalId).one() : null
if (access?.canWrite != true || !(ec.user.isInGroup('ADMIN') || ec.user.isInGroup('ZENITH_ADMIN')) || !org || org == '_NA_' || terminal?.organizationPartyId != org) { ec.message.addError('This shop cannot change that terminal.'); return }
ec.service.sync().name('delete#zenith.erp.pos.PosTerminalSalesMode').parameters([terminalId:terminalId,salesModeId:salesModeId]).call()

def _psById = [:]; (priceSourceList ?: []).each { _psById[it.enumId] = it.description }
def _short = { s -> s == null ? '' : s.toString().replaceAll(/\s*\(.*?\)/, '').trim() }
def _esc = { s -> s == null ? '' : s.toString().replace('&','&amp;').replace('<','&lt;').replace('>','&gt;').replace('"','&quot;').replace("'",'&#39;') }
def C = 'fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"'
def svgBag = '<svg viewBox="0 0 24 24" ' + C + '><path d="M6 2 3 6v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2V6l-3-4Z"/><path d="M3 6h18"/><path d="M16 10a4 4 0 0 1-8 0"/></svg>'
def svgTrash = '<svg viewBox="0 0 24 24" aria-hidden="true" ' + C + '><path d="M3 6h18M9 6V3h6v3M6 6l1 15h10l1-15M10 10v7M14 10v7"/></svg>'
def svgUsers = '<svg viewBox="0 0 24 24" ' + C + '><path d="M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2"/><circle cx="9" cy="7" r="4"/><path d="M22 21v-2a4 4 0 0 0-3-3.87"/><path d="M16 3.13a4 4 0 0 1 0 7.75"/></svg>'
def svgSliders = '<svg viewBox="0 0 24 24" ' + C + '><line x1="21" x2="14" y1="4" y2="4"/><line x1="10" x2="3" y1="4" y2="4"/><line x1="21" x2="12" y1="12" y2="12"/><line x1="8" x2="3" y1="12" y2="12"/><line x1="21" x2="16" y1="20" y2="20"/><line x1="12" x2="3" y1="20" y2="20"/><line x1="14" x2="14" y1="2" y2="6"/><line x1="8" x2="8" y1="10" y2="14"/><line x1="16" x2="16" y1="18" y2="22"/></svg>'
// order + theme keyed by mode identity so it reads like the mockup (Retail/violet, Wholesale/blue, Custom/green)
def _prio = { mm -> def n = (mm.modeName ?: '').toLowerCase(); (n.contains('retail') || mm.isDefault == 'Y') ? 0 : (n.contains('wholesale') || n.contains('bulk')) ? 1 : (n.contains('custom') || n.contains('special') || n.contains('project')) ? 2 : 3 }
def _ordered = activeModeList.findAll { mm -> !modeShopScope.activeShopId ||
    !removedShopModes.any { it.salesModeId == mm.salesModeId && it.facilityId == modeShopScope.activeShopId } }.sort(false) { _prio(it) }
def _cycleT = ['b','g','v']; def _cycleI = [svgUsers, svgSliders, svgBag]; int _i = 0
def _tiles = new StringBuilder()
_ordered.each { m ->
    def isDef = (m.isDefault == 'Y')
    def _n = (m.modeName ?: '').toLowerCase()
    def theme, iconSvg
    if (isDef || _n.contains('retail')) { theme = 'v'; iconSvg = svgBag }
    else if (_n.contains('wholesale') || _n.contains('bulk')) { theme = 'b'; iconSvg = svgUsers }
    else if (_n.contains('custom') || _n.contains('special') || _n.contains('project')) { theme = 'g'; iconSvg = svgSliders }
    else { theme = _cycleT[_i % 3]; iconSvg = _cycleI[_i % 3]; _i++ }
    def psLabel = _short(_psById[m.priceSource] ?: m.priceSource)
    def taxLabel = (m.isTaxInclusive == 'Y') ? 'Yes' : 'No'
    def reqLabel = (m.requireCustomer == 'Y') ? 'Yes' : 'No'
    def disc = (m.discountPercent ?: 0); def markup = (m.markupPercent ?: 0)
    _tiles.append('<div class="smode-tile ').append(theme).append('"><div class="smode-tile-hd"><span class="smode-tile-ico">').append(iconSvg).append('</span><span class="smode-tile-name">').append(_esc(m.modeName)).append('</span>')
    if (isDef) _tiles.append('<span class="smode-badge-default">Default</span>')
    if (modeCanManage && hasActiveOrg) {
        _tiles.append('<div class="smode-tile-actions"><details class="smode-menu"><summary aria-label="Customize ').append(_esc(m.modeName)).append('" title="Customize ').append(_esc(m.modeName)).append('"><span aria-hidden="true">&#9881;</span> Customize <span class="smode-menu-caret" aria-hidden="true">&#9662;</span></summary><div class="smode-menu-pop">')
        if (m.organizationPartyId == _activeOrg) {
            _tiles.append('<button type="button" onclick="var d=this.closest(&quot;.smode-tile&quot;).querySelector(&quot;dialog&quot;);this.closest(&quot;details&quot;).open=false;d.showModal();d.querySelector(&quot;[name=modeName]&quot;).focus()">&#9998; &nbsp;Rename</button>')
        } else {
            _tiles.append('<p class="smode-menu-note">Shared pricing definition. Delete removes it only from your organization.</p><a href="#smode-org-rules">Configure this shop&#39;s order rules</a>')
        }
        if (!isDef && modeShopScope.shopList) _tiles.append('<button type="button" onclick="this.closest(&quot;details&quot;).open=false;this.closest(&quot;.smode-tile&quot;).querySelector(&quot;.smode-shop-dialog&quot;).showModal()">Remove from selected shops</button>')
        _tiles.append('</div></details>')
        if (!isDef) {
            _tiles.append('<form method="post" action="').append(_esc(_salesModeBase)).append('/deleteMode" onsubmit="return confirm(&quot;Delete this sales mode from your organization? It will disappear from Sales Mode and all billing terminals. Existing bills remain unchanged.&quot;)"><input type="hidden" name="salesModeId" value="').append(_esc(m.salesModeId)).append('"/><input type="hidden" name="moquiSessionToken" value="').append(_esc(ec.web.sessionToken)).append('"/><button type="submit" class="smode-delete" aria-label="Delete ').append(_esc(m.modeName)).append('" title="Delete sales mode from your organization">').append(svgTrash).append('</button></form>')
        } else {
            _tiles.append('<button type="button" class="smode-delete" disabled aria-label="Delete ').append(_esc(m.modeName)).append('" title="The default sales mode cannot be deleted">').append(svgTrash).append('</button>')
        }
        _tiles.append('</div>')
    }
    _tiles.append('</div><dl style="margin:0">')
    _tiles.append('<div class="smode-fact"><dt>Price Source</dt><dd>').append(psLabel ?: '&#8212;').append('</dd></div>')
    _tiles.append('<div class="smode-fact"><dt>Discount</dt><dd>').append(disc).append('%</dd></div>')
    _tiles.append('<div class="smode-fact"><dt>Markup</dt><dd>').append(markup).append('%</dd></div>')
    _tiles.append('<div class="smode-fact"><dt>Tax Inclusive</dt><dd>').append(taxLabel).append('</dd></div>')
    _tiles.append('<div class="smode-fact"><dt>Require Customer</dt><dd>').append(reqLabel).append('</dd></div></dl>')
    if (m.description) _tiles.append('<div class="smode-tile-foot">').append(_esc(m.description)).append('</div>')
    def removedCount = removedShopModes.count { it.salesModeId == m.salesModeId }
    if (removedCount) _tiles.append('<p class="smode-menu-note">Removed from ').append(removedCount).append(' shop(s). <a href="#smode-removed-shops">View or restore</a></p>')
    if (modeCanManage && m.organizationPartyId && m.organizationPartyId == _activeOrg) {
        _tiles.append('<dialog class="smode-edit-dialog"><div class="smode-dialog-head"><h3>Customize ').append(_esc(m.modeName)).append('</h3><button type="button" aria-label="Close" onclick="this.closest(&quot;dialog&quot;).close()">&times;</button></div><form method="post" action="').append(_esc(_salesModeBase)).append('/updateMode"><input type="hidden" name="salesModeId" value="').append(_esc(m.salesModeId)).append('"/><input type="hidden" name="moquiSessionToken" value="').append(_esc(ec.web.sessionToken)).append('"/>')
        _tiles.append('<label>Mode name<input name="modeName" maxlength="100" required value="').append(_esc(m.modeName)).append('"/></label><label>Code<input name="modeCode" maxlength="12" pattern="[A-Za-z0-9_]{2,12}" required value="').append(_esc(m.modeCode)).append('"/></label><label>Price source<select name="priceSource">')
        (supportedPriceSourceList ?: []).each { opt -> _tiles.append('<option value="').append(_esc(opt.enumId)).append('"').append(m.priceSource == opt.enumId ? ' selected' : '').append('>').append(_esc(opt.description)).append('</option>') }
        _tiles.append('</select></label><div class="smode-edit-pair"><label>Discount %<input name="discountPercent" type="number" min="0" max="100" step="0.01" value="').append(_esc(disc)).append('"/></label><label>Markup %<input name="markupPercent" type="number" min="0" step="0.01" value="').append(_esc(markup)).append('"/></label></div>')
        _tiles.append('<div class="smode-edit-pair"><label>Tax inclusive<select name="isTaxInclusive"><option value="N"').append(m.isTaxInclusive == 'Y' ? '' : ' selected').append('>No</option><option value="Y"').append(m.isTaxInclusive == 'Y' ? ' selected' : '').append('>Yes</option></select></label><label>Require customer<select name="requireCustomer"><option value="N"').append(m.requireCustomer == 'Y' ? '' : ' selected').append('>No</option><option value="Y"').append(m.requireCustomer == 'Y' ? ' selected' : '').append('>Yes</option></select></label></div>')
        _tiles.append('<label>Minimum order amount<input name="minOrderAmount" type="number" min="0" step="0.01" value="').append(_esc(m.minOrderAmount ?: 0)).append('"/></label><label>Invoice prefix<input name="invoicePrefix" maxlength="20" value="').append(_esc(m.invoicePrefix)).append('"/></label><label>Color code<input name="colorCode" pattern="#[0-9a-fA-F]{6}" value="').append(_esc(m.colorCode ?: '#7C3AED')).append('"/></label><label>Description<textarea name="description" maxlength="1000" rows="3">').append(_esc(m.description)).append('</textarea></label>')
        _tiles.append('<div class="smode-dialog-actions"><button type="button" onclick="this.closest(&quot;dialog&quot;).close()">Cancel</button><button type="submit">Save changes</button></div></form></dialog>')
    }
    if (modeCanManage && hasActiveOrg && !isDef) {
        _tiles.append('<dialog class="smode-edit-dialog smode-shop-dialog"><div class="smode-dialog-head"><h3>Remove ').append(_esc(m.modeName)).append(' from shops</h3><button type="button" aria-label="Close" onclick="this.closest(&quot;dialog&quot;).close()">&times;</button></div><p>Select the shops where this mode should stop appearing. Other shops, prices and existing bills stay unchanged.</p><form method="post" action="').append(_esc(_salesModeBase)).append('/removeFromShops"><input type="hidden" name="salesModeId" value="').append(_esc(m.salesModeId)).append('"/><input type="hidden" name="moquiSessionToken" value="').append(_esc(ec.web.sessionToken)).append('"/>')
        modeShopScope.shopList.each { shop ->
            if (!removedShopModes.any { it.salesModeId == m.salesModeId && it.facilityId == shop.id }) {
                _tiles.append('<label class="smode-shop-choice"><input type="checkbox" name="facilityIds" value="').append(_esc(shop.id)).append('"').append(modeShopScope.activeShopId == shop.id || modeShopScope.shopList.size() == 1 ? ' checked' : '').append('/><span>').append(_esc(shop.name)).append('</span></label>')
            }
        }
        _tiles.append('<div class="smode-dialog-actions"><button type="button" onclick="this.closest(&quot;dialog&quot;).close()">Cancel</button><button type="submit">Remove from selected shops</button></div></form></dialog>')
    }
    _tiles.append('</div>')
}
context.tilesHtml = _tiles.length() ? ('<div class="smode-tiles">' + _tiles.toString() + '</div>') : '<div class="smode-info">No sales modes yet — create one on the left.</div>'
def restores = new StringBuilder()
if (modeCanManage) removedShopModes.each { removed ->
    def shop = modeShopScope.shopList.find { it.id == removed.facilityId }
    def mode = activeModeList.find { it.salesModeId == removed.salesModeId }
    if (shop && mode && (!modeShopScope.activeShopId || modeShopScope.activeShopId == shop.id)) {
        restores.append('<form method="post" action="').append(_esc(_salesModeBase)).append('/restoreForShop" class="smode-restore-row"><span>').append(_esc(mode.modeName)).append(' — ').append(_esc(shop.name)).append('</span><input type="hidden" name="salesModeId" value="').append(_esc(mode.salesModeId)).append('"/><input type="hidden" name="facilityId" value="').append(_esc(shop.id)).append('"/><input type="hidden" name="moquiSessionToken" value="').append(_esc(ec.web.sessionToken)).append('"/><button type="submit">Restore for this shop</button></form>')
    }
}
context.shopRestoreHtml = restores.length() ? '<section id="smode-removed-shops" class="smode-card"><h2 class="smode-card-title">Removed from shops</h2>' + restores + '</section>' : ''
